#!/usr/bin/perl############################################################################### LahuParse.pl## Mike Brodhead# 6/94## Parses Wordstar files of JAM's Dictionary of Lahu and outputs the# data in Lexware format.  Also transliterates DL format Lahu characters# into appropriate characters in STEDT font.################################################################################ TODO:#	better handling of various gloss band names (for ease of markup later on)#	how to handle supersctipting (\x14) and italics (\x19)?  leave them?#	put various files into subfolders#	split preprocessing into separate program?#	unknown Lahu characters## (non-essential)#	numbered glosses - compount band names?#	test 'study'#	check for unterminated notes#	handle glosses that don't begin until the next line#	handle run-on lexemes  -- certain lines appear in both ex and xx bands...#	preserve hierarchy below 2nd level#	em dash (\x1F)###############################################################################$start_time = time;################################################################################ for debugging expediency.  remove later....#$ARGV[0] = '*s-ning:Common:STEDTniks:mkb:Projects:Lahu Conversion:LH-A1.TXE';###############################################################################require "StandardFile.pl";unless (@ARGV){	if (&MacPerl'Answer('Process an entire folder or one file?','Folder','One File'))	{		$dirname = &StandardFile'GetFolder("Choose a folder", ":::");		opendir(DIR, $dirname);		@files = readdir(DIR);		closedir(DIR);		foreach (@files)		{			if (/^BASE\./)		# only process BASE files			{				push(ARGV, $dirname . ':' . $_);			}		}	}	else	{		$ARGV[0] = &StandardFile'GetFile("Please choose a file:", "TEXT", "::");	}}require 'lexware.ph';################################################################################ The constants that follow are used by the &convert subroutine.## Characters in $unchanged are passed unmolested.# Strictly speaking the charatcer pairs 'qh', 'kh', 'ch', 'th', and 'ph'# are each a discrete unit.  For speed and simplicity (and with no loss of# precision), the program treats those pairs like any other characters. $unchanged =  ' (),-=aiueogjdnbmhyfvl' . 'qkctp' . 'h' . "w*rs\'&z/\x19";# $stedt_char{} is a lookup table for translating to STEDT font.  The# subscript is the Lahu Dictionary character and the value at that subscript# is the STEDT Font equivalent.$stedt_char{'_'} = "\xAD";      # triple-dash (a small circle in STEDT font)$stedt_char{'|'} = "\xD1\xAD";  # quadruple-dash (a small circle w/over-bar in STEDT font)#$stedt_char{'\x08'} = "\x08";   # backspace# The following six diacritics sometimes appear on their own.  When they# appear above other characters in LD, the sequence is char. + BS (08)# + diacritic.  For STEDT font, this sequence needs to be reversed to# diacritic + char.## See &convert...$stedt_char{':'} = "\x7C";      # acute accent$stedt_char{'!'} = "\x89";      # circumflex$stedt_char{';'} = "\x5C";      # grave accent$stedt_char{'0'} = "\xC7";      # hacheck$stedt_char{'?'} = "\xD9";      # umlaut$stedt_char{']'} = "\xD5";      # over-ring# note that the tilde appears both as an alternation tilde (in which case#  it has spaces around it) and as an over-tilde (in which case it will be#  preceded by a backspace in the Lahu Dictionary).  The latter case is#  quite rare and we are ignoring it for now.$stedt_char{'~'} = "\xB1";      # alternation tilde$stedt_char{'@'} = "\xE4";      # epsilon$stedt_char{'%'} = "\xBF";      # open-o$stedt_char{'^'} = "\x95";      # barred-i$stedt_char{'$'} = "\xFA";      # schwa$stedt_char{'Q'} = "\x7C\x61";  # a acute$stedt_char{'I'} = "\x7C\x94";  # i acute$stedt_char{'U'} = "\x7C\x75";  # u acute$stedt_char{'E'} = "\x7C\x65";  # e acute$stedt_char{'O'} = "\x7C\x6F";  # o acute$stedt_char{'W'} = "\x7C\xE4";  # epsilon acute$stedt_char{'T'} = "\x7C\xBF";  # open-o acute$stedt_char{'Y'} = "\x7C\x95";  # barred-i acute$stedt_char{'R'} = "\x7C\xFA";  # schwa acute$stedt_char{'Z'} = "\xC8\x61";  # a circumflex$stedt_char{'<'} = "\xC8\x94";  # i circumflex$stedt_char{'M'} = "\xC8\x75";  # u circumflex$stedt_char{'C'} = "\xC8\x65";  # e circumflex$stedt_char{'>'} = "\xC8\x6F";  # o circumflex$stedt_char{'X'} = "\xC8\xE4";  # epsilon circumflex$stedt_char{'B'} = "\xC8\xBF";  # open-o circumflex$stedt_char{'N'} = "\xC8\x95";  # barred-i circumflex$stedt_char{'V'} = "\xC8\xFA";  # schwa circumflex$stedt_char{'A'} = "\x5C\x61";  # a grave$stedt_char{'K'} = "\x5C\x94";  # i grave$stedt_char{'J'} = "\x5C\x75";  # u grave$stedt_char{'D'} = "\x5C\x65";  # e grave$stedt_char{'L'} = "\x5C\x6F";  # o grave$stedt_char{'S'} = "\x5C\xE4";  # epsilon grave$stedt_char{'G'} = "\x5C\xBF";  # open-o grave$stedt_char{'H'} = "\x5C\x95";  # barred-i grave$stedt_char{'F'} = "\x5C\xFA";  # schwa grave$stedt_char{'1'} = "\xD1\x61";  # a bar$stedt_char{'8'} = "\xD1\x94";  # i bar$stedt_char{'7'} = "\xD1\x75";  # u bar$stedt_char{'3'} = "\xD1\x65";  # e bar$stedt_char{'9'} = "\xD1\x6F";  # o bar$stedt_char{'2'} = "\xD1\xE4";  # epsilon bar$stedt_char{'5'} = "\xD1\xBF";  # open-o bar$stedt_char{'6'} = "\xD1\x95";  # barred-i bar$stedt_char{'4'} = "\xD1\xFA";  # schwa bar$stedt_char{'}'} = "\xD9\x67";  # g umlaut$stedt_char{'P'} = "\xC7\x73";  # s hacheck$stedt_char{'{'} = "\xB3";      # ng$stedt_char{'\\'} = "\xD6";		# glottal stop (from single backslash)############################################################################### This subroutine converts the actual Lahu charatcters into the appropriate# characters in STEDT font.#sub convert{	local($lahu) = @_;	local(@chars, $char, @converted);	#print LOG "$. before $lahu\n";		###############	# In the original Dictionary of Lahu text, certain diacritics appear alone	# or over other characters in non-Lahu languages; these diacritics need to	# be converted into STEDT font.	# When the diacritics appear over other characters, the DL format is:	#     character + backspace (08) + diacritic	# which in STEDT font we convert to:	#     diacritic + character	# When the diacritics appear alone, the DL format is simply:	#     diacritic	# whereas in STEDT font we need:	#     diacritic + space	# Thus whenever diacritics appear alone in DL format, we insert a space	# followed by a backspace; then we change all occurences of	#     character + backspace + diacritic	# to  diacritic + character.			$lahu =~ s/([^\x08]):/$1 \x08:/g;	$lahu =~ s/([^\x08])!/$1 \x08!/g;	$lahu =~ s/([^\x08]);/$1 \x08;/g;	$lahu =~ s/([^\x08])0/$1 \x080/g;	$lahu =~ s/([^\x08])\?/$1 \x08?/g;	$lahu =~ s/([^\x08])\]/$1 \x08]/g;		while($lahu =~ /(.)\x08(.)/)	{		$lahu = $` . $2 . $1 . $«;	}			@chars = split (//, $lahu);	foreach (@chars)	{		$char = '';				last if ($_ eq "\x11");						if (index ($unchanged, $_) >= $[)		{			push(@converted, $_);		}		else		{			$char = $stedt_char{$_};			if ($char)			{				push(@converted, $char);			}			else			{#				print  STDERR "*** Barf!  Unknown Lahu character.  ($_, "#					 . ord($_) . ") ***:  $ARGV,Line $.\n";								print  LOG "*** Barf!  Unknown Lahu character.  ($_, "					 . ord($_) . ") ***:  $ARGV,Line $.\n";								push(@converted, $_);			}		}	}		return (join('', @converted));}sub gloss_purge{	if ($gloss)	{		if ($gloss =~ /\*/)		{			print LOG "*** Warning!!  Asterisk in gloss  (gp:$.) ***:  $gloss\n";					}			if (($gloss =~ /^id\.(.*)$/) || ($gloss =~ /^Id\.(.*)$/) ||			($gloss =~ /^ibid\.(.*)$/) || ($gloss =~ /^Ibid\.(.*)$/))		# gloss contains an 'Ibid'		{			$gloss = $prev_gloss . ' ' . $1;			#print LOG "Ibid.  (gp:$.) ***:  $gloss\n";		}			$gloss =~ tr/ / /s;					# remove redundant spaces		$gloss =~ s/\x1F //g;				# remove hyphens		$gloss =~ tr/\x11\x12\x17//d;		# Remove all that funny stuff.				print OUT $lw_gloss . $gloss_id . $lw_delim . $gloss . "\n";		$prev_gloss = $gloss;		$gloss = '';	}}sub note_purge{	&gloss_purge;	local($_) = $note;		if ($_)	{		tr/ / /s;				# Remove redundant spaces.		s/\x1F //g;				# remove hyphens		tr/\x11\x12\x17//d;		# Remove all that funny stuff.		print OUT $lw_note . $_ . "\n";		$note = '';	}}print STDERR "\n\n--------------------------------------------------------------\n";print STDERR $#ARGV . " files to parse.\n\n";foreach $basefile (@ARGV){	$basefile =~ /^(.*:)([^:]*)$/ || die "Complete confusion.  Give up.  Give up.\n";	$path = $1;	$fname = $2;	if ($fname =~ /BASE\.(.*)/)	{		$corename = $1	}	else	{		print $fname . "\n";		die "Intruder Alert!  Not a BASE file.  Security team to the bridge...\n";	}	print STDERR "LahuParse now crunching on $basefile\n";		open(BASE, $basefile)  || die "Couldn't open base file $basefile.\n";	$outfile =  $path . 'lex.' . $corename;	open(OUT, '>'. $outfile)  || die "Couldn't create output file $outfile.\n";	$logfile =  $path . 'LOG.' . $corename;	open(LOG, '>'. $logfile)  || die "Couldn't create log file $logfile.\n";		$gloss = '';	$prev_gloss = '';	$note = '';		while (<BASE>)	{		chop;					# Delete trailing newline				next if ($_ eq '');		# Skip empty lines		next if (/^\./);		# Skip lines begining w/ a period (they are								# wordstar commands)		# Remove subscripting.		while (/^([^\x12]*)\x12([^\x11]*)\x11(.*)$/)		{			$_ = $1 . $2 . $3;		}								#################		# Handle lines with partial Lahu sequences.  (ie, sequences that		# began on a previous line or will end on a subsequent line.)  Add		# the necessary control characters so that these lines will be 		# transliterated.		if ($incomplete)		# We found a partial Lahu run last time.		{			/^(\s*)(\S)(.*)$/  || 				print LOG "*** Barf!  Regexp failed.  (inc:$.) ***:  $_\n";			$_ = $1 . "\x17" . $2 . $3;			$incomplete = 0;		# Clear the flag.		}		if (/^(.*)\x17([^\x11]*)$/)		# Sequence begins on this line.		{			$_ = $1 . "\x17" . $2 . "\x11";			#print STDERR "$. found partial line:  $_\n";			$incomplete = 1;		# Set a flag so we can fix the next line.		}				# Done fixing partial runs of Lahu text.		#################				########################################################################		# Transliteration to STEDT font is done here.		#		# We locate three regions of the input line:  An initial plain text		# part, a run of Lahu text, and the remainder.  (The remainder may		# contain further runs of Lahu text.)  We pass the Lahu part to the		# &convert subroutine and then begin the process over on the remainder		# of the line.		#		# When we fail to locate a Lahu part, we are done parsing that line		# and we move on.		#		# \x17 and \x11 are retained because they will make parsing easier.		#				$plain = '';		$new = '';		while ($_)		{			if (/^([^\x17]*)\x17([^\x11]*)\x11(.*)$/)			{				$plain = $1;				$_ = $3;				$new = $new . $plain . "\x17" . &convert($2) . "\x11";			}			else			{				$new = $new . $_;				$_ = '';			}		}		$_ = $new;						# Now we deal with the superscripts and transliterate them.				$plain = '';		$new = '';		while ($_)		{			#print STDERR "$.:  Searching for superscripts...\n";			if (/^([^\x14]*)\x14([^\x14]*)\x14(.*)$/)			{				#print STDERR "$.:  Found a superscript.\n";				$plain = $1;				$_ = $3;				$tone_marks = $2;								$tone_marks =~ tr/1234567890/\xC1\xAA\xA3\xA2\xB0\xA4\xA6\xA5\xBB\xBC/;								$new = $new . $plain . $tone_marks;			}			else			{				$new = $new . $_;				$_ = '';			}		}		#print STDERR "$.:  Transliteration done.\n";				$_ = $new;		# Transliteration done.		########################################################################			# Deal w/ Multiple Lahu runs here.		# remember: slash, pos, or three spaces delimit end of lexeme		# when it runs past col 35.		# strip all but first \x17 and all but last \x11, then let		# regular parse routine deal with it.			if (/\x17.*\x17/ && !(/^\s*\//) && !($note))		# Multiple Lahu runs in the line.		# Improperly terminated runs may couse problems here....		{			#print STDERR "before $.:  $_\n";			$lahu_end = rindex($_, "\x11");			if ($lahu_end <= 35)			# We can be sure that the Lahu is confined to the Lexeme			{								/^([^\x17]*)\x17(.*)\x11([^\x11]*)$/;				$left = $1;				$middle = $2;				$right = $3;								$middle =~ tr/\x17\x11//d;				$_ = $left . "\x17" . $middle . "\x11" . $right;			}						elsif (/( \/ )(.*)/ )  # there is a slash between lexeme and gloss			{								$lxm = $`;				$gls = $2;				$delim = $1;								#print STDERR "$.   $lxm\n$delim\n$gls\n";								$lxm =~ /^([^\x17]*)\x17(.*)\x11([^\x11]*)$/;				$left = $1;				$middle = $2;				$right = $3;				$middle =~ tr/\x17\x11//d;				$_ = $left . "\x17" . $middle . "\x11" . $right . $delim . $gls;							}						elsif (/(\x11[^\x17]*)(  \([^\)]*\) )(.*)/)  # pos between lex and gloss			{								$lxm = $` . $1;				$gls = $3;				$delim = $2;				#print STDERR "$.   $lxm\n$delim\n$gls\n";								$lxm =~ /^([^\x17]*)\x17(.*)\x11([^\x11]*)$/;				$left = $1;				$middle = $2;				$right = $3;				$middle =~ tr/\x17\x11//d;				$_ = $left . "\x17" . $middle . "\x11" . $right . $delim . $gls;							}						elsif (/(\S   )(.*)/)   # three spaces separate lexeme and gloss			{								$lxm = $`;				$gls = $2;				$delim = $1;				#print STDERR "$.   $lxm\n$delim\n$gls\n";								$lxm =~ /^([^\x17]*)\x17(.*)\x11([^\x11]*)$/;				$left = $1;				$middle = $2;				$right = $3;				$middle =~ tr/\x17\x11//d;				$_ = $left . "\x17" . $middle . "\x11" . $right . $delim . $gls;							}						#print STDERR "after $.:  $_\n";		}				$right = $left = $middle = $delim = $gls = $lxm = '';					# 1159 seconds w/o		#study;					# May or may not speed things up		#######################################################################		# Determine the type of line and take approp. action		#######################################################################        $line = $_;		########################################		# Line is a numbered gloss; at least 10 spaces followed by a letter or		#  digit, followed by a period and then the gloss itself.		#    e.g.                 b. rational discourse		#$1 = $2 = $3 = $4 = '';				if (/^           +((\d+)|([a-z]))(\. +)((\[[^\]]+\] +)*)(.+)$/)		# was if (/^           +((\d+)|([a-z]))(\. +) (.+)$/)		{			$temp = $1 . $4 . $7;			&gloss_purge;			if ($5)			{				$bz = $5;				print OUT $lw_bz . $bz . "\n";			}			$lw_gloss = 'ngl ';			$gloss = $temp;		}				##################################		# Line is continuation of a gloss; the last line was a gloss (the		#   $gloss variable isn't empty) and we start in column 35.		elsif ( ($gloss) && /^ {35,}(.*) */)		{			$next_line = $1;			if (!($gloss =~ /[^-]-$/))  # add a space if gloss doesn't end in hyphen			{				$gloss = $gloss . ' ';			}			$gloss = $gloss . $next_line;   # any extra spaces will get trimmed later		}								##################################		# Line is continuation of a note; the last line was an unfinished note		elsif ( ($note) && /^ +(.*) *$/)		{			if (/^ +(.*) *\/ *$/)			# line is the last of the note			{				$note = $note . ' ' . $1;				&note_purge;			}			else			{				/^ +(.*) *$/;				$note = $note . ' ' . $1;			}			}						#####################		# Begin new headword; line is neither a numbered gloss or a continuation		#  and starts in first column		elsif (/^\S/)				# was elsif (/^\x17/)				{						# First, output any gloss in progress.			&gloss_purge;				    # because of our multiple Lahu runs routine above, the entire		    #  headword is always flanked by the Lahu text codes x17 and x11			if (/^\x17([^\x11]*)\x11(.*)$/)			# Extract headword			{				$hw = $1;				$_ = $2;			}			else			{				print LOG "*** Barf!  Couldn't extract headword.  ($.) ***:  $line\n";				$hw = '';							}						print OUT $lw_hw . $hw . "\n";						$pos = '';			$loan = '';			$gloss = '';			$gloss_id = '';		# To distinguish multiple glosses for a								# given headword.			$ex = '';			$exgl = '';			$note = '';			$bz = '';									# Sometimes a "  [q.v.]" appears after the headword but before			#  the part of speech.			if (/^ +(\[q+\.v\.\])(.*)/)			{				$qv = $1;				$_ = $2;				print OUT $lw_bz . $qv . "\n";			}						# if a part of speech is present, it will be exactly two spaces			#  after the headword, inside parentheses, followed by a space.			if (/^ +\(([^\)]*)\) (.*)$/)	# Extract part of speech			{				$pos = $1;				$_ = $2;				print OUT $lw_pos . $pos . "\n";			}						# between the part of speech and the gloss, the word LOAN or LOAN?			#  may appear, preceeded by at least one space and followed by at			#  least a space.			if (/^ +(LOAN\??) (.*)$/) 			{				$loan = $1;				$_ = $2;				print OUT $lw_loan . $loan . "\n";			}			# preceding the gloss may be a dialect notation or gloss			#  characterization, in square brackets.  The gloss follows			#  after one space.  In a numbered gloss these notations would			#  follow the gloss number.			if (/^ *((\d+)|([a-z]))(\. +)((\[[^\]]+\] +)+)(.+)$/)			{				$bz = $5;				$_ = $1 . $4 . $7;				print OUT $lw_bz . $bz . "\n";			}			elsif (/^ *((\[[^\]]+\] +)+)(.+)$/)			{				$bz = $1;				$_ = $3;				print OUT $lw_bz . $bz . "\n";			}						$lw_gloss = 'gl  ';						# Now whatever's left, not including white space, is the gloss.			if (/^\s*(\S.*)\s*$/)			{				$gloss = $1;			}			else			{				print OUT $lw_xx . $line . "\n";				print LOG "*** Barf!  Couldn't extract gloss.  (hw:$.) ***:  $line\n";			}		}				###############		# sub-headword; not a headword (there's white space first),		#  not a note (there's no slash at beginning of text), and not		#  an example (no slash between lexeme and gloss)				elsif (/^( {5})+([^\s\/])?\x17.*(\([^\)]*\))? +(\S.*) */ && !(/ \//) && !(/\x11\//))		# was elsif (/^( {5})+\x17.*\([^\)]*\) +(\S.*) */)		#   then was elsif (/^( {5})+(\S)?\x17.*\([^\)]*\) +(\S.*) */)		{			# First, output any gloss in progress.			&gloss_purge;			/(\S)?\x17([^\x11]*)\x11([^\(\s]*)(.*)$/;	# Extract sub-headword			# was /\x17([^\x11]*)\x11/;	# Extract sub-headword			# was $shw = $1;			$shw = $1 . $2 . $3;			$_ = $4;			print OUT $lw_shw . $shw . "\n";			$pos = '';			$loan = '';			$gloss = '';			$gloss_id = '';		# To distinguish multiple glosses for a								# given headword.			$ex = '';			$exgl = '';			$note = '';			$bz = '';						# Sometimes a "  [q.v.]" appears after the headword but before			#  but before the part of speech.			if (/^ +(\[q+\.v\.\])(.*)/)			{				$qv = $1;				$_ = $2;				print OUT $lw_bz . $qv . "\n";			}			# if a part of speech is present, it will be exactly two spaces			#  after the headword, inside parentheses, followed by a space.			if (/^ +\(([^\)]*)\) (.*)$/)	# Extract part of speech			{				$pos = $1;				$_ = $2;				print OUT $lw_pos . $pos . "\n";			}			# if there's no part of speech and the hw ends in "ve", then			#  we're dealing with a verb.  Otherwise, it's an error.			elsif ($shw =~ / ve *$/)			{				$pos = 'V';				print OUT $lw_pos . $pos . "\n";			}			else			{				print LOG "*** Barf!  No part of speech for headword $shw\n"; 			}						# between the part of speech and the gloss, the word LOAN or LOAN?			#  may appear, preceeded by at least one space and followed by at			#  least a space.			if (/^ +(LOAN\??) (.*)$/) 			{				$loan = $1;				$_ = $2;				print OUT $lw_loan . $loan . "\n";			}			# preceding the gloss may be a dialect notation or gloss			#  characterization, in square brackets.  The gloss follows			#  after one space.  In a numbered gloss these notations would			#  follow the gloss number.			if (/^ *((\d+)|([a-z]))(\. +)((\[[^\]]+\] +)+)(.+)$/)			{				$bz = $5;				$_ = $1 . $4 . $7;				print OUT $lw_bz . $bz . "\n";			}			elsif (/^ *((\[[^\]]+\] +)+)(.+)$/)			{				$bz = $1;				$_ = $3;				print OUT $lw_bz . $bz . "\n";			}						$lw_gloss = 'gl  ';						# Now whatever's left, not including white space, is the gloss.			if (/^\s*(\S.*)\s*$/)			{				$gloss = $1;			}			else			{				print OUT $lw_xx . $line . "\n";				print LOG "*** Barf!  Couldn't extract gloss.  (hw:$.) ***:  $line\n";			}		}				###############		# example text		elsif (/^( {5})+(\S)?\x17(.*) (\x11)?\//)		# was elsif (/^( {5})+\x17/)		{			# First, output any gloss in progress.			&gloss_purge;			$pos = '';			if (/(\S)?\x17([^\x11]*)\x11([^\/]*)/)			# was if (/\x17([^\(]*)\x11/)			# Extract example & gloss			{				$ex = $1 . $2 . $3;				# was $ex = $1;				print OUT $lw_ex . $ex . "\n";			}			else			{				print OUT $lw_xx . $_ . "\n";				print LOG "*** Barf!  Couldn't extract example.  (ex:$.) ***:  $line\n";							}						$lw_gloss = 'exgl';						if (/\x11 +\(([^\)]*)\) *\/? *(.*) */)			# part of speech is indicated			{				$pos = $1;				$gloss = $2;				print OUT $lw_pos . $pos . "\n";											}			elsif (/\x11 *\/ +(.*) */)			# example and gloss are separated by a slash			{				$gloss = $1;			}			else			{				print OUT $lw_xx . $_ . "\n";				print LOG "*** Barf!  Couldn't extract gloss.  (ex:$.) ***:  $line\n";			}		}				#######		# note		elsif (/^ +\//)		{			&gloss_purge;		# first things first...						if (/^ +\/ *(.*) *\/ *$/)			# note begins and ends on this line			{				$note = $1;				&note_purge;			}			else			# note will continue onto other lines			{				/^ +\/ *(.*) *$/;				$note = $1;			}		}				#############		# Unknown...		else		{			# should there be a gloss purge here? (note purge?)			&note_purge;			print OUT $lw_xx . $_ . "\n";			print LOG "Unknown line ($.):  $line\n";		}	}	close(BASE);	close(OUT);	close(LOG);	&MacPerl'SetFileInfo('R*ch', 'TEXT', $outfile);	&MacPerl'SetFileInfo('R*ch', 'TEXT', $logfile);	#print "Done.\n";	}print STDERR "Elapsed time (seconds):  " . (time - $start_time) . "\n";